begin;
alter table public.vault_shopify_discount_application_observations add column completeness_source_content_fingerprint text;
alter table public.vault_shopify_line_discount_allocation_observations add column completeness_source_content_fingerprint text;
alter table public.vault_shopify_discount_application_observations drop constraint vault_shopify_discount_application_contract_identity_key;
alter table public.vault_shopify_line_discount_allocation_observations drop constraint vault_shopify_line_discount_allocation_contract_identity_key;
create unique index vault_shopify_discount_application_unlinked_identity_key on public.vault_shopify_discount_application_observations(source,shopify_order_id,application_index,order_source_updated_at,fingerprint_contract_version) where completeness_source_content_fingerprint is null;
create unique index vault_shopify_discount_application_linked_identity_key on public.vault_shopify_discount_application_observations(source,shopify_order_id,application_index,order_source_updated_at,fingerprint_contract_version,completeness_source_content_fingerprint) where completeness_source_content_fingerprint is not null;
create unique index vault_shopify_line_discount_allocation_unlinked_identity_key on public.vault_shopify_line_discount_allocation_observations(source,shopify_order_id,shopify_line_item_id,application_index,order_source_updated_at,fingerprint_contract_version) where completeness_source_content_fingerprint is null;
create unique index vault_shopify_line_discount_allocation_linked_identity_key on public.vault_shopify_line_discount_allocation_observations(source,shopify_order_id,shopify_line_item_id,application_index,order_source_updated_at,fingerprint_contract_version,completeness_source_content_fingerprint) where completeness_source_content_fingerprint is not null;
create unique index vault_shopify_financial_capture_current_version_key on public.vault_shopify_financial_capture_completeness_observations(source,shopify_order_id,order_source_updated_at,fingerprint_contract_version) where fingerprint_contract_version='shopify-source-content-v1';
alter table public.vault_shopify_discount_application_observations add constraint vault_shopify_discount_application_completeness_fk foreign key(source,shopify_order_id,order_source_updated_at,fingerprint_contract_version,completeness_source_content_fingerprint) references public.vault_shopify_financial_capture_completeness_observations(source,shopify_order_id,order_source_updated_at,fingerprint_contract_version,source_content_fingerprint);
alter table public.vault_shopify_line_discount_allocation_observations add constraint vault_shopify_line_discount_allocation_completeness_fk foreign key(source,shopify_order_id,order_source_updated_at,fingerprint_contract_version,completeness_source_content_fingerprint) references public.vault_shopify_financial_capture_completeness_observations(source,shopify_order_id,order_source_updated_at,fingerprint_contract_version,source_content_fingerprint);
create or replace function public.require_shopify_discount_capture_link() returns trigger language plpgsql as $$
begin
  if new.fingerprint_contract_version='shopify-source-content-v1' and new.completeness_source_content_fingerprint is null then
    new.completeness_source_content_fingerprint:=nullif(current_setting('vault.financial_capture_fingerprint',true),'');
  end if;
  if new.fingerprint_contract_version='shopify-source-content-v1' and new.completeness_source_content_fingerprint is null then raise exception 'MISSING_FINANCIAL_CAPTURE_LINK'; end if;
  return new;
end $$;
create trigger require_shopify_discount_application_capture_link before insert on public.vault_shopify_discount_application_observations for each row execute function public.require_shopify_discount_capture_link();
create trigger require_shopify_line_allocation_capture_link before insert on public.vault_shopify_line_discount_allocation_observations for each row execute function public.require_shopify_discount_capture_link();
alter function public.record_shopify_financial_evidence(jsonb,text) rename to record_shopify_financial_evidence_base;
revoke all on function public.record_shopify_financial_evidence_base(jsonb,text) from public,anon,authenticated,service_role;
create function public.record_shopify_financial_evidence(payload jsonb,capture_mode text) returns void language plpgsql security definer set search_path=pg_catalog,public as $$
declare c record; apps int; allocs int; distinct_apps int; distinct_allocs int;
begin
  if capture_mode not in ('prospective','historical') or payload is null then raise exception 'INVALID_FINANCIAL_CAPTURE'; end if;
  select * into c from jsonb_to_record(payload->'completeness') as x(source text,shopify_order_id text,order_source_updated_at timestamptz,discount_application_count int,discount_allocation_count int,refund_count int,refund_line_count int,refund_transaction_count int,discount_applications_complete boolean,line_items_complete boolean,refunds_complete boolean,refund_lines_complete boolean,refund_transactions_complete boolean,observed_at timestamptz,payload_fingerprint text,fingerprint_contract_version text,source_content_fingerprint text,evidence_mode text);
  if c.source='shopify' and c.fingerprint_contract_version='shopify-source-content-v1' then
    if not (c.discount_applications_complete and c.line_items_complete and c.refunds_complete and c.refund_lines_complete and c.refund_transactions_complete) or c.payload_fingerprint is distinct from c.source_content_fingerprint then raise exception 'INCOMPLETE_FINANCIAL_CAPTURE'; end if;
    select count(*),count(distinct application_index) into apps,distinct_apps from jsonb_to_recordset(coalesce(payload->'applications','[]')) as x(application_index int);
    select count(*),count(distinct (shopify_line_item_id,application_index)) into allocs,distinct_allocs from jsonb_to_recordset(coalesce(payload->'allocations','[]')) as x(shopify_line_item_id text,application_index int);
    if apps<>c.discount_application_count or apps<>distinct_apps or allocs<>c.discount_allocation_count or allocs<>distinct_allocs then raise exception 'FINANCIAL_CAPTURE_COUNT_MISMATCH'; end if;
    if exists(select 1 from jsonb_to_recordset(coalesce(payload->'allocations','[]')) as a(application_index int) where not exists(select 1 from jsonb_to_recordset(coalesce(payload->'applications','[]')) as p(application_index int) where p.application_index=a.application_index)) then raise exception 'UNLINKED_DISCOUNT_ALLOCATION'; end if;
    if exists(select 1 from jsonb_to_recordset(coalesce(payload->'applications','[]')) as x(completeness_source_content_fingerprint text) where x.completeness_source_content_fingerprint is distinct from c.source_content_fingerprint)
       or exists(select 1 from jsonb_to_recordset(coalesce(payload->'allocations','[]')) as x(completeness_source_content_fingerprint text) where x.completeness_source_content_fingerprint is distinct from c.source_content_fingerprint) then raise exception 'FINANCIAL_CAPTURE_LINK_MISMATCH'; end if;
    if exists(select 1 from public.vault_shopify_financial_capture_completeness_observations e where e.source=c.source and e.shopify_order_id=c.shopify_order_id and e.order_source_updated_at=c.order_source_updated_at and e.fingerprint_contract_version=c.fingerprint_contract_version and e.source_content_fingerprint<>c.source_content_fingerprint) then raise exception 'FINANCIAL_SOURCE_VERSION_CONFLICT'; end if;
    insert into public.vault_shopify_financial_capture_completeness_observations(source,evidence_mode,shopify_order_id,order_source_updated_at,discount_application_count,discount_allocation_count,refund_count,refund_line_count,refund_transaction_count,discount_applications_complete,line_items_complete,refunds_complete,refund_lines_complete,refund_transactions_complete,observed_at,payload_fingerprint,fingerprint_contract_version,source_content_fingerprint)
    values(c.source,c.evidence_mode,c.shopify_order_id,c.order_source_updated_at,c.discount_application_count,c.discount_allocation_count,c.refund_count,c.refund_line_count,c.refund_transaction_count,c.discount_applications_complete,c.line_items_complete,c.refunds_complete,c.refund_lines_complete,c.refund_transactions_complete,c.observed_at,c.payload_fingerprint,c.fingerprint_contract_version,c.source_content_fingerprint) on conflict do nothing;
    if exists(select 1 from public.vault_shopify_financial_capture_completeness_observations e where e.source=c.source and e.shopify_order_id=c.shopify_order_id and e.order_source_updated_at=c.order_source_updated_at and e.fingerprint_contract_version=c.fingerprint_contract_version and e.source_content_fingerprint<>c.source_content_fingerprint) then raise exception 'FINANCIAL_SOURCE_VERSION_CONFLICT'; end if;
    perform set_config('vault.financial_capture_fingerprint',c.source_content_fingerprint,true);
  end if;
  perform public.record_shopify_financial_evidence_base(payload,capture_mode);
end $$;
revoke all on function public.record_shopify_financial_evidence(jsonb,text) from public,anon,authenticated;
grant execute on function public.record_shopify_financial_evidence(jsonb,text) to service_role;
revoke all on public.vault_shopify_discount_application_observations,public.vault_shopify_line_discount_allocation_observations,public.vault_shopify_financial_capture_completeness_observations from public,anon,authenticated,service_role;
grant select on public.vault_shopify_discount_application_observations,public.vault_shopify_line_discount_allocation_observations,public.vault_shopify_financial_capture_completeness_observations to service_role;
revoke all on public.vault_shopify_line_zero_discount_allocation_observations from public,anon,authenticated,service_role;
grant select on public.vault_shopify_line_zero_discount_allocation_observations to service_role;
create or replace view public.vault_shopify_resolved_line_discount_evidence with (security_barrier=true,security_invoker=true) as
with complete_capture_versions as (select source,shopify_order_id,order_source_updated_at,fingerprint_contract_version,count(*) filter(where discount_applications_complete and line_items_complete and refunds_complete and refund_lines_complete and refund_transactions_complete) valid_complete_capture_count from public.vault_shopify_financial_capture_completeness_observations where fingerprint_contract_version='shopify-source-content-v1' group by source,shopify_order_id,order_source_updated_at,fingerprint_contract_version), captures as (select c.* from public.vault_shopify_financial_capture_completeness_observations c join complete_capture_versions v using(source,shopify_order_id,order_source_updated_at,fingerprint_contract_version) where v.valid_complete_capture_count=1 and c.discount_applications_complete and c.line_items_complete and c.refunds_complete and c.refund_lines_complete and c.refund_transactions_complete), linked_apps as (select a.* from public.vault_shopify_discount_application_observations a join captures c on (c.source,c.shopify_order_id,c.order_source_updated_at,c.fingerprint_contract_version,c.source_content_fingerprint)=(a.source,a.shopify_order_id,a.order_source_updated_at,a.fingerprint_contract_version,a.completeness_source_content_fingerprint)), linked_allocations as (select a.* from public.vault_shopify_line_discount_allocation_observations a join linked_apps p on p.source=a.source and p.shopify_order_id=a.shopify_order_id and p.order_source_updated_at=a.order_source_updated_at and p.application_index=a.application_index and p.completeness_source_content_fingerprint=a.completeness_source_content_fingerprint), valid_capture as (select c.source,c.shopify_order_id,c.order_source_updated_at,c.source_content_fingerprint,c.discount_application_count,c.discount_allocation_count from captures c where (select count(*) from linked_apps p where (p.source,p.shopify_order_id,p.order_source_updated_at,p.completeness_source_content_fingerprint)=(c.source,c.shopify_order_id,c.order_source_updated_at,c.source_content_fingerprint))=c.discount_application_count and (select count(*) from linked_allocations a where (a.source,a.shopify_order_id,a.order_source_updated_at,a.completeness_source_content_fingerprint)=(c.source,c.shopify_order_id,c.order_source_updated_at,c.source_content_fingerprint))=c.discount_allocation_count), line_allocations as (select a.source,a.shopify_order_id,a.order_source_updated_at,a.shopify_line_item_id,a.completeness_source_content_fingerprint,sum(a.allocated_shop_amount) source_discount_allocation from linked_allocations a join valid_capture c on (c.source,c.shopify_order_id,c.order_source_updated_at,c.source_content_fingerprint)=(a.source,a.shopify_order_id,a.order_source_updated_at,a.completeness_source_content_fingerprint) where a.payload_fingerprint=a.source_content_fingerprint and a.allocated_shop_currency='GBP' and (a.allocated_presentment_currency is null or a.allocated_presentment_currency='GBP') group by a.source,a.shopify_order_id,a.order_source_updated_at,a.shopify_line_item_id,a.completeness_source_content_fingerprint), zero_proofs as (select z.source,z.shopify_order_id,z.order_source_updated_at,z.shopify_line_item_id,count(*) proof_rows,bool_and(z.evidence_method='PROVEN_ZERO_DISCOUNT_ALLOCATION' and z.payload_fingerprint=z.source_content_fingerprint and c.source_content_fingerprint=z.completeness_source_content_fingerprint and z.discount_application_count=c.discount_application_count and z.discount_allocation_count=c.discount_allocation_count) valid,max(z.source_content_fingerprint) source_content_fingerprint from public.vault_shopify_line_zero_discount_allocation_observations z join valid_capture c on (c.source,c.shopify_order_id,c.order_source_updated_at,c.source_content_fingerprint)=(z.source,z.shopify_order_id,z.order_source_updated_at,z.completeness_source_content_fingerprint) group by z.source,z.shopify_order_id,z.order_source_updated_at,z.shopify_line_item_id)
select l.order_id,o.shopify_order_id,l.id order_line_id,l.shopify_line_item_id,o.currency,l.quantity*l.unit_price gross_line_revenue,l.discount_allocation canonical_discount_allocation,a.source_discount_allocation,case when f.order_id is not null and a.source_discount_allocation is not null and coalesce(z.proof_rows,0)=0 then a.source_discount_allocation when f.order_id is not null and z.valid and z.proof_rows>0 and a.source_discount_allocation is null then 0 when coalesce(f.discount_allocation_count,0)=0 then l.discount_allocation end resolved_discount_allocation,case when f.order_id is not null and a.source_discount_allocation is not null and coalesce(z.proof_rows,0)=0 then l.quantity*l.unit_price-a.source_discount_allocation when f.order_id is not null and z.valid and z.proof_rows>0 and a.source_discount_allocation is null then l.quantity*l.unit_price when coalesce(f.discount_allocation_count,0)=0 then l.quantity*l.unit_price-l.discount_allocation end resolved_net_line_revenue,case when f.order_id is not null and a.source_discount_allocation is not null and coalesce(z.proof_rows,0)=0 then 'resolved_source_backed' when f.order_id is not null and z.valid and z.proof_rows>0 and a.source_discount_allocation is null then 'resolved_source_backed' when coalesce(f.discount_allocation_count,0)=0 then 'canonical_fallback' else 'unresolved' end resolution_status,case when f.order_id is not null and a.source_discount_allocation is not null and coalesce(z.proof_rows,0)=0 then 'SHOPIFY_IMMUTABLE_LINE_DISCOUNT_ALLOCATION' when f.order_id is not null and z.valid and z.proof_rows>0 and a.source_discount_allocation is null then 'PROVEN_ZERO_DISCOUNT_ALLOCATION' when coalesce(f.discount_allocation_count,0)=0 then 'CANONICAL_LINE_DISCOUNT_ALLOCATION' else 'UNRESOLVED' end evidence_method,coalesce(a.completeness_source_content_fingerprint,z.source_content_fingerprint) provenance_fingerprint from public.vault_shopify_order_lines l join public.vault_shopify_orders o on o.id=l.order_id left join public.vault_shopify_verified_order_financials f on f.order_id=o.id left join line_allocations a on a.source=o.source and a.shopify_order_id=o.shopify_order_id and a.order_source_updated_at=o.shopify_updated_at and a.shopify_line_item_id=l.shopify_line_item_id left join zero_proofs z on z.source=o.source and z.shopify_order_id=o.shopify_order_id and z.order_source_updated_at=o.shopify_updated_at and z.shopify_line_item_id=l.shopify_line_item_id;
revoke all on public.vault_shopify_resolved_line_discount_evidence from public,anon,authenticated;
grant select on public.vault_shopify_resolved_line_discount_evidence to service_role;
notify pgrst,'reload schema';
commit;
